using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Reflection;using System.Security.Cryptography;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class CityMobileVerify{const string R="FinalEnvironmentRoadReview/MobileOptimization/";static CityMobileVerify(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||EditorApplication.isPlayingOrWillChangePlaymode||!File.Exists("CityMobileVerify.request"))return;File.Delete("CityMobileVerify.request");try{Run();}catch(Exception e){File.WriteAllText(R+"Verification.txt",e.ToString());Debug.LogException(e);}}
static string Hash(string p){using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(File.ReadAllBytes(p))).Replace("-","").ToLowerInvariant();}
static void Run(){var sc=SceneManager.GetActiveScene();var all=sc.GetRootGameObjects();var render=all.SelectMany(g=>g.GetComponentsInChildren<MeshRenderer>(true)).ToArray();var lods=all.SelectMany(g=>g.GetComponentsInChildren<LODGroup>(true)).ToArray();var s=new StringBuilder();int malformed=0,uncontrolledFar=0;var counts=new Dictionary<Renderer,int>();foreach(var group in lods){float previous=2;foreach(var l in group.GetLODs()){if(l.screenRelativeTransitionHeight>=previous||l.renderers.Any(r=>!r))malformed++;previous=l.screenRelativeTransitionHeight;}foreach(var r in group.GetLODs().SelectMany(l=>l.renderers).Where(r=>r).Distinct()){if(!counts.ContainsKey(r))counts[r]=0;counts[r]++;}}foreach(var r in render.Where(r=>r.name.StartsWith("Mobile LOD")&&r.gameObject.activeInHierarchy))if(!counts.ContainsKey(r))uncontrolledFar++;int overlapping=counts.Count(p=>p.Value>1);if(malformed>0||uncontrolledFar>0||overlapping>0)throw new Exception("LOD invalid="+malformed+" uncontrolled far="+uncontrolledFar+" renderer used by multiple levels/groups="+overlapping);
var mats=render.SelectMany(r=>r.sharedMaterials).Where(m=>m).Distinct().ToArray();foreach(var m in mats)if(ShaderUtil.ShaderHasError(m.shader))throw new Exception("Shader error "+m.name);int sourceHashes=0;if(File.Exists("FinalEnvironmentRoadReview/CityGroundTextureMeshHashes.txt"))foreach(var row in File.ReadAllLines("FinalEnvironmentRoadReview/CityGroundTextureMeshHashes.txt")){var t=row.Split('|');if(Hash(t[0])!=t[1].Replace("-","").ToLowerInvariant())throw new Exception("Original ground source changed "+t[0]);sourceHashes++;}
var reduced=AssetDatabase.FindAssets("t:Mesh",new[]{"Assets/Scenes/Oasis/MobileOptimization/Meshes"}).Select(g=>AssetDatabase.LoadAssetAtPath<Mesh>(AssetDatabase.GUIDToAssetPath(g))).ToArray();foreach(var m in reduced){if(m.vertexCount<3||m.vertices.Any(p=>float.IsNaN(p.x)||float.IsInfinity(p.x)))throw new Exception("Invalid reduced mesh");for(int sub=0;sub<m.subMeshCount;sub++)if(m.GetTriangles(sub).Any(i=>i<0||i>=m.vertexCount))throw new Exception("Invalid mesh indices");}
CityMobileOptimizationMeasure.Write(sc,R+"Visibility-Final.csv");var cap=typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic);cap.Invoke(null,new object[]{sc,new Vector3(-32,58,-351.9f),new Vector3(-115,36,-351.9f),"MobileOptimization/Hospital-Final"});cap.Invoke(null,new object[]{sc,new Vector3(-62,32,230),new Vector3(-62,31,320),"MobileOptimization/Street-Final"});cap.Invoke(null,new object[]{sc,new Vector3(222,39,295),new Vector3(222,31,255),"MobileOptimization/Coffee-Final"});foreach(string name in new[]{"Hospital","Street","Coffee"}){var a=new Texture2D(2,2);var b=new Texture2D(2,2);a.LoadImage(File.ReadAllBytes(R+name+"-Before.png"));b.LoadImage(File.ReadAllBytes(R+name+"-After.png"));var ca=a.GetPixels32();var cb=b.GetPixels32();double sum=0;long noticeable=0;for(int i=0;i<ca.Length;i++){int d=Math.Abs(ca[i].r-cb[i].r)+Math.Abs(ca[i].g-cb[i].g)+Math.Abs(ca[i].b-cb[i].b);sum+=d;if(d>60)noticeable++;}s.AppendLine(name+" before/after mean RGB byte difference="+(sum/(3*ca.Length)).ToString("F3")+" pixels with summedRGBdiff>60="+(100.0*noticeable/ca.Length).ToString("F2")+"% (animated foliage, water, flags and signals can vary)");UnityEngine.Object.DestroyImmediate(a);UnityEngine.Object.DestroyImmediate(b);}
var folder="FinalEnvironmentRoadBackup/BeforeMobileOptimization/Assets/Assets";int textureMetas=0;foreach(string backup in Directory.GetFiles(folder,"*.meta",SearchOption.AllDirectories)){string original="Assets"+backup.Substring(folder.Length);if(!File.Exists(original))continue;string before=File.ReadAllText(backup),after=File.ReadAllText(original);foreach(string key in new[]{"maxTextureSize:","format:","textureCompression:","compressionQuality:","textureFormat:"}){Func<string,string[]> values=t=>t.Split('\n').Select(v=>v.Trim()).Where(v=>v.StartsWith(key)).Distinct().OrderBy(v=>v).ToArray();if(!values(before).SequenceEqual(values(after)))throw new Exception("Texture quality field changed: "+original+" "+key);}textureMetas++;}
s.AppendLine("SUCCESS scene="+sc.path+" LOD groups="+lods.Length+" mesh renderers="+render.Length+" unique used materials="+mats.Length+" reduced shared meshes="+reduced.Length+" shaders with errors=0; invalid/overlapping LOD references=0; uncontrolled far renderers=0; original ground mesh/UV source hashes preserved="+sourceHashes+"; texture import quality settings preserved="+textureMetas+". No mesh joining. Existing material/texture counts retained. Android hardware profiling pending; ADB device list empty.");File.WriteAllText(R+"Verification.txt",s.ToString());EditorSceneManager.SaveScene(sc);}
}
